import * as React from 'react';
import * as S from '@primasoftllc/design-system';
import '@primasoftllc/design-system/styles.css';

function Placement() {
    var objects = React.useState(['Volvo FH16', 'Scania R450', 'MAN TGX']), setObjects = objects[1];
    var open = React.useState(false), setOpen = open[1], name = React.useState(''), setName = name[1];
    var error = React.useState(''), setError = error[1], message = React.useState(''), setMessage = message[1];
    var formRef = React.useRef(null), trigger = React.useRef(null), wasOpen = React.useRef(false);
    React.useLayoutEffect(function () {
        if (open[0])
            formRef.current.querySelector('input').focus();
        else if (wasOpen.current)
            trigger.current.focus();
        wasOpen.current = open[0];
    }, [open[0]]);
    function start(e) {
        trigger.current = e.currentTarget;
        if (open[0]) {
            formRef.current.querySelector('input').focus();
            return;
        }
        setName('');
        setError('');
        setMessage('');
        setOpen(true);
    }
    function cancel() { setOpen(false); setMessage('Добавление отменено.'); }
    function submit(e) {
        e.preventDefault();
        var value = name[0].trim();
        if (!value) {
            setError('Введите название объекта.');
            formRef.current.querySelector('input').focus();
            return;
        }
        setObjects(function (items) { return items.concat(value); });
        setOpen(false);
        setMessage('Объект «' + value + '» добавлен.');
    }
    return <div className={"demo-stack"}>
    <div className={'stage'}>
    <p>
    {'Объекты'}
    </p>
    <ul className={'items'}>
    {objects[0].map(function (item, i) {
            return <li key={i}>
    {item}
    </li>;
        })}
    </ul>
    <div className={'stage-action'}>
    <S.DsFab label={'Добавить объект'} extended={true} aria-expanded={open[0]} aria-controls={open[0] ? 'object-form' : undefined} onClick={start}/>
    </div>
    </div>
    {open[0] ? <form id={'object-form'} ref={formRef} className={'object-form'} noValidate={true} aria-label={'Добавление объекта'} onSubmit={submit}>
    <S.DsField label={'Название объекта'} required={true} value={name[0]} error={error[0] || undefined} onChange={function (e) { setName(e.target.value); setError(''); }}/>
    <div className={'form-actions'}>
    <S.DsButton tone={'secondary'} onClick={cancel}>
    {'Отмена'}
    </S.DsButton>
    <S.DsButton type={'submit'}>
    {'Добавить'}
    </S.DsButton>
    </div>
    </form> : null}
    <p role={'status'} aria-label={'Результат создания объекта'}>
    {message[0]}
    </p>
    </div>;
}
function App() {
    var message = React.useState('Нажмите кнопку, чтобы выполнить действие.'), setMessage = message[1];
    var timer = React.useRef(null);
    React.useEffect(function () { return function () { clearTimeout(timer.current); }; }, []);
    return <div className="dsfab-example">
    <style>{exampleStyles}</style>
    <Placement />
    </div>;
}

const exampleStyles = ".dsfab-example{font:var(--ds-type-body);color:var(--ds-fg)}\n.dsfab-example .demo-stack{display:flex;flex-direction:column;gap:16px;min-width:0}\n.dsfab-example p{margin:0}\n.dsfab-example .stage{position:relative;min-height:240px;padding:16px 16px 88px;background:var(--ds-bg);border:1px solid var(--ds-border);border-radius:var(--ds-radius-md)}\n.dsfab-example .stage-action{position:absolute;right:16px;bottom:16px}\n.dsfab-example .items{margin:12px 0 0;padding-left:24px;overflow-wrap:anywhere}\n.dsfab-example .object-form{display:flex;flex-direction:column;gap:16px;max-width:360px;min-width:0}\n.dsfab-example .form-actions{display:flex;flex-wrap:wrap;justify-content:flex-end;gap:12px}";

export { App as Example };

