import * as React from 'react';
import * as S from '@primasoftllc/design-system';
import '@primasoftllc/design-system/styles.css';

function App() {
    var saving = React.useState(false), setSaving = saving[1], saved = React.useState('Готово к добавлению.'), setSaved = saved[1];
    var timer = React.useRef(null);
    React.useEffect(function () { return function () { clearTimeout(timer.current); }; }, []);
    function save() { setSaving(true); setSaved('Добавляем объект…'); timer.current = setTimeout(function () { setSaving(false); setSaved('Объект добавлен.'); }, 1200); }
    return <div className="dsfab-example">
    <style>{exampleStyles}</style>
    <div className={"demo-stack"}>
    <div className={'row'}>
    <S.DsFab label={'Добавить объект'} loading={saving[0]} onClick={save}/>
    <S.DsFab label={'Добавить объект'} extended={true} loading={saving[0]} onClick={save}/>
    </div>
    <p role={'status'} aria-label={'Результат добавления'}>
    {saved[0]}
    </p>
    </div>
    </div>;
}

